import sys

def longest_pal_brute(s: str) -> str:
    n = len(s)
    best = s[0]
    for i in range(n):
        for j in range(i, n):
            t = s[i:j + 1]
            if t == t[::-1] and len(t) > len(best):
                best = t
    return best

if __name__ == '__main__':
    s = sys.stdin.readline().rstrip('\n')
    print(longest_pal_brute(s))
